/// <summary>
/// Activates the vendor invoice workflow.
/// </summary>
public void submit()
{
    this.metValidateSubmissionForInvoiceMatching();
    next submit();
}

/// <summary>
/// Reactivates the vendor invoice header workflow.
/// </summary>
public void reSubmit()
{
    this.metValidateSubmissionForInvoiceMatching();
    next reSubmit();
}

/// <summary>
/// validates if the vendor invoice can be submitted/resubmitted to workflow according to invoice matching requirements
/// </summary>
private void metValidateSubmissionForInvoiceMatching()
{
    if(!vendInvoiceInfoTable.purchTable().isInterCompanyOrder() || !vendInvoiceInfoTable.METClaimInvoice)
    {
        if(!vendInvoiceInfoTable.MetImportAmount)
        {
            throw error("@MET:NoInvAmtNoGST");
        }
        else
        {
            if(vendInvoiceInfoTable.displayMetVariance() && !vendInvoiceInfoTable.displayMETVarInTolerance())
            {
                throw error("@MET:VarOutTol");
            }
        }
    }
}
